/**
 * Emits the generated half of `@ghxstship/xos-sdk`: schema types, the operation table, one resource
 * class per API resource and the `XosClient` that wires them together.
 */
import type { ApiIR, JsonSchema, OperationIR, ParamIR } from "./ir.ts";
import { refName } from "./ir.ts";
import { camelCase, pascalCase, tsIdentifier, tsPropertyKey } from "./names.ts";

export const GENERATED_BANNER =
  "// Generated by @ghxstship/xos-sdk codegen from packages/api/openapi/v1.json. Do not edit; run `pnpm --filter @ghxstship/xos-sdk generate`.";

const CORE_MEMBERS = new Set(["baseUrl", "request", "requestPage", "paginate", "constructor"]);

function comment(lines: readonly string[], indent = ""): string {
  const body = lines.flatMap((l) => l.split("\n")).map((l) => l.replace(/\*\//g, "*\\/").trimEnd());
  while (body.length > 0 && body[body.length - 1] === "") body.pop();
  if (body.length === 0) return "";
  return `${indent}/**\n${body.map((l) => `${indent} *${l ? ` ${l}` : ""}`).join("\n")}\n${indent} */\n`;
}

function literal(value: unknown): string {
  return JSON.stringify(value);
}

function isNullOnly(s: JsonSchema): boolean {
  const keys = Object.keys(s).filter((k) => k !== "description" && k !== "example");
  if (keys.length !== 1 || keys[0] !== "type") return false;
  const types = Array.isArray(s.type) ? s.type : [s.type];
  return types.includes("null");
}

/** TypeScript type for a JSON Schema fragment. */
export function tsType(s: JsonSchema): string {
  if (s.$ref) return refName(s.$ref);
  if (s.allOf) {
    // `allOf: [$ref, { type: [T, "null"] }]` is how the contract marks a nullable reference.
    const nullable = s.allOf.find(isNullOnly);
    const rest = s.allOf.filter((m) => m !== nullable);
    const inner = rest.map((m) => wrap(tsType(m))).join(" & ");
    return nullable ? `${wrap(inner)} | null` : inner;
  }
  const union = s.anyOf ?? s.oneOf;
  if (union) return [...new Set(union.map(tsType))].join(" | ");
  if (s.enum) return s.enum.map(literal).join(" | ");
  const types = s.type === undefined ? [] : Array.isArray(s.type) ? s.type : [s.type];
  if (types.length === 0) return s.properties ? objectType(s) : "unknown";
  return [...new Set(types.map((t) => primitive(t as string, s)))].join(" | ");
}

function wrap(t: string): string {
  return /[|&]/.test(t) ? `(${t})` : t;
}

function primitive(type: string, s: JsonSchema): string {
  switch (type) {
    case "string":
      return "string";
    case "integer":
    case "number":
      return "number";
    case "boolean":
      return "boolean";
    case "null":
      return "null";
    case "array":
      return `ReadonlyArray<${s.items ? tsType(s.items) : "unknown"}>`;
    case "object":
      return objectType(s);
    default:
      throw new Error(`Unsupported JSON Schema type ${type}`);
  }
}

function propertyDoc(s: JsonSchema): string[] {
  const lines: string[] = [];
  if (s.description) lines.push(s.description);
  const facts: string[] = [];
  if (s.format) facts.push(`Format: \`${s.format}\`.`);
  if (typeof s["pattern"] === "string") facts.push(`Pattern: \`${s["pattern"]}\`.`);
  if (typeof s["minLength"] === "number" || typeof s["maxLength"] === "number") {
    facts.push(`Length: ${s["minLength"] ?? 0} to ${s["maxLength"] ?? "unbounded"}.`);
  }
  if (typeof s["minimum"] === "number" || typeof s["maximum"] === "number") {
    facts.push(`Range: ${s["minimum"] ?? "unbounded"} to ${s["maximum"] ?? "unbounded"}.`);
  }
  if (facts.length > 0) lines.push(facts.join(" "));
  return lines;
}

function objectType(s: JsonSchema): string {
  const props = Object.entries(s.properties ?? {});
  const required = new Set(s.required ?? []);
  const extra =
    s.additionalProperties && typeof s.additionalProperties === "object"
      ? `{ readonly [key: string]: ${tsType(s.additionalProperties)} }`
      : null;
  // Index signatures rather than `Record`: the contract has a schema named `Record`.
  if (props.length === 0) return extra ?? "{ readonly [key: string]: unknown }";
  const members = props
    .map(([name, schema]) => {
      const optional = required.has(name) ? "" : "?";
      return `${comment(propertyDoc(schema), "  ")}  readonly ${tsPropertyKey(name)}${optional}: ${tsType(schema)};`;
    })
    .join("\n");
  const shape = `{\n${members}\n}`;
  return extra ? `${shape} & ${extra}` : shape;
}

function emitSchemas(ir: ApiIR): string {
  const out: string[] = [GENERATED_BANNER, "/* Component schemas of the XOS public API. */", ""];
  for (const { name, schema } of ir.schemas) {
    const doc = comment(schema.description ? [schema.description] : []);
    const type = tsType(schema);
    // A union of object shapes (`anyOf`, such as AutomationConditions) is a type alias, never an interface.
    const isUnion = schema.anyOf !== undefined || schema.oneOf !== undefined;
    const isPlainObject =
      !isUnion && type.startsWith("{\n") && type.endsWith("}") && !type.includes("} & {");
    out.push(
      isPlainObject
        ? `${doc}export interface ${name} ${type}\n`
        : `${doc}export type ${name} = ${type};\n`,
    );
  }
  return out.join("\n");
}

function operationSpec(op: OperationIR): string {
  const spec = {
    id: op.id,
    resource: op.resource,
    verb: op.verb,
    method: op.method,
    path: op.path,
    pathParams: op.pathParams.map((p) => p.name),
    queryParams: op.queryParams.map((p) => p.name),
    requiredQueryParams: op.queryParams.filter((p) => p.required).map((p) => p.name),
    paged: op.paged,
    fields: op.fields,
    idempotent: op.idempotent,
    ifMatch: op.ifMatch,
    body: op.body,
    bodyRequired: op.bodyRequired,
    successStatus: op.successStatus,
    response: op.response,
    item: op.item,
    tag: op.tag,
    summary: op.summary,
    capability: op.capability,
    scopes: op.scopes,
  };
  return `  ${literal(op.id)}: ${JSON.stringify(spec)},`;
}

function emitOperations(ir: ApiIR): string {
  const ids = ir.operations.map((o) => `  | ${literal(o.id)}`).join("\n");
  const resources = ir.resources
    .map(
      (r) =>
        `  { name: ${literal(r.name)}, tag: ${literal(r.tag)}, operations: [${r.operations.map((o) => literal(o.id)).join(", ")}] },`,
    )
    .join("\n");
  const tags = ir.tags
    .map((t) => `  { name: ${literal(t.name)}, description: ${literal(t.description)} },`)
    .join("\n");
  return `${GENERATED_BANNER}
import type { OperationSpec } from "../runtime/types.ts";

/** Version of the OpenAPI document this SDK was generated from. */
export const API_VERSION = ${literal(ir.version)};
export const API_TITLE = ${literal(ir.title)};

/** Every operation id in the API. */
export type OperationId =
${ids};

export interface ResourceInfo {
  readonly name: string;
  readonly tag: string;
  readonly operations: readonly OperationId[];
}

/** Every operation, keyed by operation id. */
export const OPERATIONS: Readonly<Record<OperationId, OperationSpec>> = {
${ir.operations.map(operationSpec).join("\n")}
};

/** Resources in document order, each with its operations. */
export const RESOURCES: readonly ResourceInfo[] = [
${resources}
];

/** Module tags with their descriptions. */
export const TAGS: readonly { readonly name: string; readonly description: string }[] = [
${tags}
];
`;
}

function extraParamsType(params: readonly ParamIR[]): string | null {
  if (params.length === 0) return null;
  const members = params
    .map(
      (p) =>
        `${comment(p.description ? [p.description] : [], "  ")}  readonly ${tsPropertyKey(p.name)}${p.required ? "" : "?"}: ${tsType(p.schema)};`,
    )
    .join("\n");
  return `{\n${members}\n}`;
}

interface MethodPlan {
  readonly signature: string[];
  readonly input: string;
}

function planMethod(op: OperationIR, listAll: boolean): MethodPlan {
  const signature: string[] = [];
  const pathEntries: string[] = [];
  for (const p of op.pathParams) {
    const name = tsIdentifier(p.name);
    // Some code schemas are nullable as columns; a path segment never is.
    const t = tsType(p.schema);
    signature.push(`${name}: ${p.schema.$ref ? `NonNullable<${t}>` : t}`);
    pathEntries.push(name === p.name ? name : `${tsPropertyKey(p.name)}: ${name}`);
  }
  const optionsType = op.ifMatch
    ? op.idempotent
      ? "$UpdateOptions & $MutationOptions"
      : "$UpdateOptions"
    : op.idempotent
      ? "$MutationOptions"
      : "$RequestOptions";
  const optionsRequired = op.ifMatch;

  if (op.body) {
    const optionalBody = !op.bodyRequired && !optionsRequired;
    signature.push(
      `body${optionalBody ? "?" : ""}: ${op.body}${!op.bodyRequired && optionsRequired ? " | undefined" : ""}`,
    );
  }

  const extra = extraParamsType(op.queryParams);
  let paramsType: string | null = null;
  if (op.paged) {
    const base = listAll ? `$ListAllParams<${op.item}>` : `$ListParams<${op.item}>`;
    paramsType = extra ? `${base} & ${extra}` : base;
  } else if (op.fields || extra) {
    const base = op.fields && op.response ? `$FieldsParams<${op.response}>` : null;
    paramsType = [base, extra].filter(Boolean).join(" & ");
  }
  const paramsRequired = op.queryParams.some((p) => p.required);
  if (paramsType) {
    signature.push(
      paramsRequired || optionsRequired
        ? `params: ${wrap(paramsType)}${paramsRequired ? "" : " | undefined"}`
        : `params?: ${paramsType}`,
    );
  }
  signature.push(`options${optionsRequired ? "" : "?"}: ${optionsType}`);

  const input: string[] = [];
  if (pathEntries.length > 0) input.push(`path: { ${pathEntries.join(", ")} }`);
  if (paramsType) input.push("query: params");
  if (op.body) input.push("body");
  return { signature, input: `{ ${input.join(", ")} }` };
}

function methodDoc(op: OperationIR, extra?: string): string {
  const lines = [op.summary, ""];
  if (op.description) lines.push(op.description, "");
  if (extra) lines.push(extra, "");
  lines.push(`\`${op.method} ${op.path}\` (operation \`${op.id}\`).`);
  if (op.capability) lines.push(`Requires the capability \`${op.capability}\`.`);
  return comment(lines, "  ");
}

function emitMethod(op: OperationIR, names: Set<string>): string {
  const name = camelCase(op.verb);
  if (names.has(name)) throw new Error(`${op.id}: method ${name} collides in ${op.resource}`);
  names.add(name);
  const spec = `$OPERATIONS[${literal(op.id)}]`;
  const plan = planMethod(op, false);
  if (op.paged) {
    const allName = `${name}All`;
    if (names.has(allName)) throw new Error(`${op.id}: method ${allName} collides`);
    names.add(allName);
    const all = planMethod(op, true);
    return `${methodDoc(op)}  ${name}(${plan.signature.join(", ")}): Promise<$Page<${op.item}>> {
    return this.client.requestPage<${op.item}>(${spec}, ${plan.input}, options);
  }

${methodDoc(op, "Iterates every item across all pages, following `next_cursor`.")}  ${allName}(${all.signature.join(", ")}): AsyncGenerator<${op.item}, void, undefined> {
    return this.client.paginate<${op.item}>(${spec}, ${all.input}, options);
  }
`;
  }
  const result = op.response ?? "undefined";
  return `${methodDoc(op)}  ${name}(${plan.signature.join(", ")}): Promise<$ApiResponse<${result}>> {
    return this.client.request<${result}>(${spec}, ${plan.input}, options);
  }
`;
}

export function resourceClassName(resource: string): string {
  return `${pascalCase(resource)}Resource`;
}

function usedSchemas(ir: ApiIR): string[] {
  const names = new Set<string>();
  for (const op of ir.operations) {
    for (const n of [op.body, op.item, op.paged ? null : op.response]) if (n) names.add(n);
    if (!op.paged && op.fields && op.response) names.add(op.response);
    for (const p of [...op.queryParams, ...op.pathParams]) {
      for (const m of JSON.stringify(p.schema).matchAll(
        /#\/components\/schemas\/([A-Za-z0-9]+)/g,
      )) {
        if (m[1]) names.add(m[1]);
      }
    }
  }
  return [...names].sort();
}

function emitResources(ir: ApiIR): string {
  const classes = ir.resources.map((r) => {
    const names = new Set<string>();
    const tag = ir.tags.find((t) => t.name === r.tag);
    const doc = comment([
      `Operations on \`${r.name}\`, in the ${r.tag} module.`,
      ...(tag?.description ? ["", tag.description] : []),
    ]);
    return `${doc}export class ${resourceClassName(r.name)} extends $Resource {
${r.operations.map((op) => emitMethod(op, names)).join("\n")}}
`;
  });
  return `${GENERATED_BANNER}
// Runtime names carry a \`$\` prefix so they never collide with a schema name.
import { Resource as $Resource } from "../runtime/client.ts";
import type {
  ApiResponse as $ApiResponse,
  FieldsParams as $FieldsParams,
  ListAllParams as $ListAllParams,
  ListParams as $ListParams,
  MutationOptions as $MutationOptions,
  Page as $Page,
  RequestOptions as $RequestOptions,
  UpdateOptions as $UpdateOptions,
} from "../runtime/types.ts";
import { OPERATIONS as $OPERATIONS } from "./operations.ts";
import type {
${usedSchemas(ir)
  .map((n) => `  ${n},`)
  .join("\n")}
} from "./schemas.ts";

${classes.join("\n")}`;
}

function emitClient(ir: ApiIR): string {
  const fields = ir.resources.map((r) => {
    const prop = camelCase(r.name);
    if (CORE_MEMBERS.has(prop)) throw new Error(`Resource ${r.name} collides with a client member`);
    return `  /** ${r.tag}: operations on \`${r.name}\`. */\n  readonly ${prop}: ${resourceClassName(r.name)} = new ${resourceClassName(r.name)}(this);`;
  });
  return `${GENERATED_BANNER}
import { XosClientCore } from "../runtime/client.ts";
import {
${ir.resources.map((r) => `  ${resourceClassName(r.name)},`).join("\n")}
} from "./resources.ts";

/**
 * Client for the ${ir.title} ${ir.version}. One property per resource; every operation in the
 * OpenAPI document is a method.
 *
 * @example
 * const xos = new XosClient({ baseUrl: "https://api.ghxstship.tech/v1", apiKey: process.env.XOS_API_KEY });
 * for await (const project of xos.projects.listAll({ filter: { project_state: { eq: "Active" } } })) {
 *   console.log(project.name);
 * }
 */
export class XosClient extends XosClientCore {
${fields.join("\n")}
}
`;
}

export interface EmittedFile {
  /** Path relative to the package root. */
  readonly path: string;
  readonly contents: string;
}

/** The TypeScript SDK files, unformatted. */
export function emitTypeScript(ir: ApiIR): EmittedFile[] {
  return [
    { path: "src/generated/schemas.ts", contents: emitSchemas(ir) },
    { path: "src/generated/operations.ts", contents: emitOperations(ir) },
    { path: "src/generated/resources.ts", contents: emitResources(ir) },
    { path: "src/generated/client.ts", contents: emitClient(ir) },
  ];
}
